/* VONDO's service worker.
 *
 * Three jobs: make the HUD open instantly with no signal, keep the fonts and
 * icons it needs, and turn a push message into a notification.
 *
 * Hand-written rather than generated by Workbox, deliberately. This file is
 * about a hundred lines and you can read all of it; a generated one is a
 * dependency you cannot debug at three in the morning when the phone shows a
 * stale screen and you cannot work out why.
 *
 * Bump CACHE when anything about the caching rules changes. The old cache is
 * deleted on activate, so a bad deploy is one version bump away from gone.
 */
const CACHE = "vondo-v3";

// The shell: enough to render something the moment the app opens offline.
// Hashed asset filenames are NOT listed — they change every build, so they are
// cached the first time they are actually fetched instead.
const SHELL = [
  "/",
  "/manifest.webmanifest",
  "/icon-192.png",
  "/icon-512.png",
  // The three faces the first screen paints with. Fetched here so the very
  // first offline launch has its typography rather than falling back to
  // system fonts and reflowing when the network returns.
  "/fonts/Barlow-400.woff2",
  "/fonts/ChakraPetch-600.woff2",
  "/fonts/JetBrainsMono-400.woff2",
];

/* What may be cached — an allow-list, not a list of exceptions.
 *
 * It was the other way round, and that was a bug: a list of API paths to skip
 * silently caches every endpoint added afterwards. `/me` and `/agenda` arrived
 * later and would have been served from cache forever, so the board would have
 * shown yesterday's diary and yesterday's numbers with no way to tell.
 *
 * Static files are safe because their names contain a build hash, so a new
 * build is a new name. Anything else is live data by default, and being wrong
 * in that direction costs a network request rather than a wrong answer.
 */
function cacheable(url) {
  if (url.pathname.startsWith("/assets/")) return true;
  if (url.pathname.startsWith("/fonts/")) return true;
  return /\.(?:js|css|woff2?|png|svg|ico|webmanifest|html)$/.test(url.pathname);
}

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(CACHE)
      // addAll fails the whole install if any single URL 404s, which would
      // leave the app with no worker at all. Individually is more forgiving.
      .then((cache) => Promise.allSettled(SHELL.map((url) => cache.add(url))))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  // Navigations: answer from cache immediately and refresh behind it.
  //
  // Network-first was correct and slow. Every cold launch waited on a round
  // trip to a free-tier server that may have been asleep — up to a minute of
  // blank screen for a shell that had not changed. Cache-first shows the app at
  // once and picks the new one up on the next launch, which is the trade every
  // installed app makes.
  //
  // The asset names carry a build hash, so a stale shell referencing a new
  // build cannot happen: index.html changes whenever the assets do, and the
  // copy written here is the new one.
  if (request.mode === "navigate") {
    event.respondWith(
      caches.match("/").then((hit) => {
        const fresh = fetch(request)
          .then((response) => {
            if (response && response.ok) {
              const copy = response.clone();
              caches.open(CACHE).then((cache) => cache.put("/", copy));
            }
            return response;
          })
          .catch(() => hit || Response.error());
        return hit || fresh;
      }),
    );
    return;
  }

  // Live data — /me, /agenda, and anything added later — is left entirely
  // alone. No cache read, no cache write; the request goes to the network as if
  // this worker did not exist.
  if (!cacheable(url)) return;

  // Hashed assets, fonts and icons are immutable by name, so the cache is
  // always right and the network is only for the first time.
  event.respondWith(
    caches.match(request).then((hit) => {
      if (hit) return hit;
      return fetch(request).then((response) => {
        if (response.ok && response.type === "basic") {
          const copy = response.clone();
          caches.open(CACHE).then((cache) => cache.put(request, copy));
        }
        return response;
      });
    }),
  );
});

/* ---------------------------------------------------------------------------
 * Notifications
 * ------------------------------------------------------------------------- */

self.addEventListener("push", (event) => {
  let payload = { title: "Jarvis", body: "", tag: "vondo" };
  try {
    payload = { ...payload, ...(event.data ? event.data.json() : {}) };
  } catch {
    // A push that isn't JSON still deserves to reach him rather than vanish.
    payload.body = event.data ? event.data.text() : "";
  }
  event.waitUntil(
    self.registration.showNotification(payload.title, {
      body: payload.body,
      icon: "/icon-192.png",
      badge: "/icon-192.png",
      tag: payload.tag,
      // Reminders should survive being missed: without this a notification that
      // arrives while the phone is face-down can auto-dismiss unseen.
      requireInteraction: payload.tag === "reminder",
      data: { url: payload.url || "/" },
    }),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const target = (event.notification.data && event.notification.data.url) || "/";
  event.waitUntil(
    self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((clients) => {
      // Focus the HUD if it is already open rather than stacking another copy.
      for (const client of clients) {
        if (client.url.includes(self.location.origin) && "focus" in client) {
          client.navigate(target);
          return client.focus();
        }
      }
      return self.clients.openWindow(target);
    }),
  );
});
